class Solution:
    def numberOfSubarrays(self, nums: List[int], k: int) -> int:
        def func(k):
            l,r,odds,count = 0,0,0,0
            while r < len(nums):
                if nums[r]%2!=0:
                    odds+=1
                if odds <= k:
                    count+=r-l+1
                else:
                    while odds > k:
                        if nums[l]%2!=0:
                            odds-=1
                        l+=1
                    count+=r-l+1
                r+=1
            return count
        return func(k) - func(k-1)

class Solution {
    public int numberOfSubarrays(int[] nums, int k) {
        int n = nums.length;

        // HashMap to store frequency of oddCount values
        HashMap<Integer, Integer> map = new HashMap<>();

        int subArrCnt = 0;  // Final count of subarrays with exactly k odd numbers
        int oddCount = 0;   // Keeps track of the number of odd elements seen so far

        // Base case: one way to have 0 odd numbers before starting
        map.put(0, 1);

      
        for (int i = 0; i < n; i++) {
            
            // If current number is odd, increment the oddCount
            if (nums[i] % 2 != 0) {
                oddCount++;
            }

            // We want to find how many subarrays have (oddCount - k) odds before index i
            int noOfOddsWanted = oddCount - k;

            // If such a count exists in the map, add its frequency to subArrCnt
            if (map.containsKey(noOfOddsWanted)) {
                int cnt = map.get(noOfOddsWanted);
                subArrCnt += cnt;
            }

            // Update the frequency of the current oddCount in the map
            if (map.containsKey(oddCount)) {
                map.put(oddCount, map.get(oddCount) + 1);
            } else {
                map.put(oddCount, 1);
            }
        }

        // Return total number of subarrays with exactly k odd numbers
        return subArrCnt;
    }
}

