int solve(vector<int>& nums, int k){
    if(k<0){
        return 0 ;
    }
   int l = 0 ;
   int r = 0 ;
   int n = nums.size() ;
   int count = 0 ;
   int subcount = 0 ;
   while(r<n){
    if(nums[r]%2!=0){
        count++ ;
    }
    while(count> k){
        if(nums[l]%2!=0){
            count-- ;
        }
        l++ ;
    }
    subcount = subcount + (r-l+1) ;
    r++ ;
   }
