Here's the postorder morris traversal(similar to preorder), the only changes are instead of finding the rightmost node in the left subtree, we find the leftmost node in the right subtree. Also, we need to keep adding the node values in the head so as to maintain the LRN order of postorder.

public List<Integer> postorderTraversal(TreeNode root) {
        List<Integer> arr = new LinkedList<>();
        TreeNode curr = root;

        while(curr != null){
            if(curr.right == null){
                arr.add(0,curr.val);
                curr = curr.left;
            }
            else{
                TreeNode temp = curr.right;
                while(temp.left != null && temp.left != curr)
                    temp = temp.left;
                if(temp.left == null){
                    temp.left = curr;
                    arr.add(0,curr.val);
                    curr = curr.right;
                }
                else{
                    temp.left = null;
                    curr = curr.left;
                }
            }
        }
        return arr;
    }

I optimized the preorder approach . instead of connecting thread to curr node we can connect the thread prev->right =  curr->right node and we can make curr->right == null. therefore we can simply move towards curr right instead of going at curr node and checking conditions again and again.here's my code

vector<int> preorderTraversal(TreeNode* root) {
         vector<int> preOrder;
        if(!root) return preOrder;

        TreeNode* curr = root;
        while(curr){
            if(curr->left){
                preOrder.push_back(curr->val);
                TreeNode* prev = curr->left;
                
                while(prev->right){
                    prev = prev->right;
                }
                    prev->right = curr->right;
                    curr->right = NULL;
                    curr = curr->left;

            }else{
                preOrder.push_back(curr->val);
                curr = curr->right;
            }
        }
        return preOrder;
    }
};

