 int search(vector<int> &nums, int low, int high){
        if(low==high) return nums[low];
        int mid = low + (high-low)/2;
        if (mid % 2 == 1) mid--;
        if(nums[mid] == nums[mid+1])
            return search(nums, mid+2, high);
