first building a prefix sum array and then using two pointers (one at the start and one at the end) to decide which card to pick next. At each step, it calculates the sum of the next k cards from the left and the last k cards from the right, then chooses the side with the larger sum (or the larger individual card if equal) and updates pointers accordingly. class Solution {
public:
    int maxScore(vector<int>& arr, int k) {
        int n=arr.size();int l=0;int r=n-1; int sum=0;
        vector<int> prefix;
        for(auto it : arr){
            sum+=it;
            prefix.push_back(sum);
        }
        int ans=0;
        while(k>0){
            // chek which side has greater sum // then pic it
            // int l_sum=prefix[l+k-1]; as left might be INCR so
            //  i need to take only l to (l+k) sum
            int prev_sum_l;
            if(l-1<0)prev_sum_l=0;
            else prev_sum_l=prefix[l-1];
            int l_sum = prefix[l+k-1] - prev_sum_l; 
            int prev_sum_r;
            if(r-k < 0)prev_sum_r=0;
            else prev_sum_r=prefix[r-k];
            int r_sum=prefix[r] - prev_sum_r;
            // if both side sum qual then take the larges betw them
            if(l_sum==r_sum){
                if(arr[l]>arr[r]){
                    ans+=arr[l];
                    l++;
                }else{
                    ans+=arr[r];
                    r--;
                }
            }
           else if(l_sum>r_sum){
                ans+=arr[l];
                l++;
            }else{
                ans+=arr[r];
                r--;
            }
            k--;
        }
        return ans;
    }
};

