class Solution {
public:
    int f(vector<int>& cardPoints, int left, int right, int k, vector<vector<int>>& dp) {
        if (k == 0) return 0;
        if (dp[left][k] != -1) return dp[left][k];
        
        // Take from left
        int takeLeft = cardPoints[left] + f(cardPoints, left + 1, right, k - 1, dp);
        // Take from right
        int takeRight = cardPoints[right] + f(cardPoints, left, right - 1, k - 1, dp);
        
        return dp[left][k] = max(takeLeft, takeRight);
    }

    int maxScore(vector<int>& cardPoints, int k) {
        int n = cardPoints.size();
        // Only need to track left index and remaining picks
        vector<vector<int>> dp(k + 1, vector<int>(k + 1, -1));
        return f(cardPoints, 0, n - 1, k, dp);
    }
};

