class Solution:
    def maxScore(self, cardPoints: List[int], k: int) -> int:
        if k == len(cardPoints):
            return sum(cardPoints)

        n = len(cardPoints)
        new_k = n-k
        
        curr_sum = sum(cardPoints[0:new_k])
        min_sum = curr_sum
        l,r = 0,new_k
        
        while r <n:
            curr_sum = curr_sum + cardPoints[r] - cardPoints[l]
            min_sum = min(min_sum,curr_sum)
            r+=1
            l+=1
        return sum(cardPoints)-min_sum

