class Solution {
public:
    int maxScore(vector<int>& cardPoints, int k) {
        int n = cardPoints.size();
        int left = n-k;
        int right = n-k;
        int ans = 0;
        int sum = 0;
        while (left < n) {

            if ((right - left + 1) <= k) {

                sum = sum + cardPoints[right % n];
                right++;

            } else {

                sum = sum + cardPoints[right % n];
                sum = sum - cardPoints[left++];
                right++;
            }
            ans = max(sum, ans);
        }
        return ans;
    }
};

